#!/usr/bin/env python3
import argparse, hashlib, json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--evidence',type=Path,required=True);p.add_argument('--raw',type=Path,required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args();e=a.evidence;errors=[]
